def triples_sum_to_zero(l: list):
    from itertools import combinations
    for combo in combinations(set(l), 3):
        if sum(combo) == 0:
            # Ensure that there are at least three occurrences of the numbers in the original list
            counts = {num: l.count(num) for num in combo}
            if all(l.count(num) >= counts[num] for num in combo):
                return True
    return False
