from typing import List

def triples_sum_to_zero(l: List[int]) -> bool:
    n = len(l)
    # Sort the list to use the two-pointer approach
    l.sort()
    for i in range(n - 2):
        # To avoid duplicate triplets, skip duplicates
        if i > 0 and l[i] == l[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False
