def correct_bracketing(brackets: str):
    stack = []
    for char in brackets:
        if char == "<":
            stack.append(char)
        elif char == ">":
            if not stack:
                return False
            stack.pop()
        else:
            # Ignore any other characters if they appear
            continue
    return len(stack) == 0
