def fibfib(n: int):
    """The FibFib number sequence is a sequence similar to the Fibonacci sequence that's defined as follows:
    fibfib(0) == 0
    fibfib(1) == 0
    fibfib(2) == 1
    fibfib(n) == fibfib(n-1) + fibfib(n-2) + fibfib(n-3).

    This implementation uses memoization to compute the n-th element efficiently.
    """
    memo = {0: 0, 1: 0, 2: 1}

    def helper(k):
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2) + helper(k - 3)
        return memo[k]

    return helper(n)

def digitSum(s):
