    Write a function that takes a string as input and returns the sum of the uppercase characters' ASCII codes.
    """
    return sum(ord(char) for char in s if char.isupper())

def pluck(arr):
    """
    Given an array representing a branch of a tree with non-negative integer nodes,
    pluck the node with the smallest even value. If multiple nodes share this value,
    choose the one with the smallest index.

    Returns:
        A list [smallest_value, index] if such a node exists, otherwise [].
    """
    if not arr:
        return []

    min_value = None
    min_index = None

    for index, value in enumerate(arr):
        if value % 2 == 0:
            if min_value is None or value < min_value:
                min_value = value
                min_index = index

    if min_value is None:
        return []

    return [min_value, min_index]
